func createRun(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		jobID := c.Param("id")
		if exists, err := st.JobExists(jobID); err != nil {
			writeJobError(c, errStorageUnavailable)
			return
		} else if !exists {
			writeJobError(c, errJobNotFound)
			return
		}

