	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, err
	}
	return job, nil
}

func scanJob(scanner rowScanner) (*Job, error) {
	job := &Job{}
	var enabled int
	var createdNS, updatedNS int64
	var nextNS sql.NullInt64
	if err := scanner.Scan(
